const r = await tools.write_stdin({session_id:27516,chars:"print('depth+coords')
M=np.array(obs.meta['cameras']['front_camera']['extrinsic_cv'],float)
K=np.array(obs.meta['cameras']['front_camera']['intrinsic_cv'],float)
def px_world(cam,u,v):
 d=float(obs.depth[cam][0,v,u])/1000
 K=np.array(obs.meta['cameras'][cam]['intrinsic_cv'],float)
 E=np.array(obs.meta['cameras'][cam]['extrinsic_cv'],float)
 pc=np.array([(u-K[0,2])*d/K[0,0],(v-K[1,2])*d/K[1,1],d])
 return np.linalg.inv(E[:3,:3])@(pc-E[:3,3])
print([(p, px_world('front_camera',*p)) for p in [(52,80),(52,120),(52,140),(218,80),(218,120),(218,140)]])
",yield_time_ms:1000,max_output_tokens:1000});
